package com.cbdog.ptvbox
import org.junit.Test
import org.junit.Assert.*
import org.json.JSONObject
class Features055Test {
 @Test fun doubanSubjectsExcludePostsAndPeopleAndKeepRealType(){val j=JSONObject("""{"contents":{"items":[{"target_type":"movie","target":{"id":"wrong","title":"not subject"}}]},"subjects":{"items":[{"target_type":"movie","target":{"id":"36238849","title":"玩具总动员5","year":"2026","rating":{"value":8.0,"count":123}}},{"target_type":"tv","target":{"id":"38405325","title":"刃牙道 第二季","year":"2026"}},{"target_type":"celebrity","target":{"id":"1","title":"人"}}]}}""");val rows=DoubanSearch055.subjects(j);assertEquals(2,rows.size);assertEquals("36238849",rows[0].id);assertEquals(123,rows[0].votes);assertEquals("tv",rows[1].kind)}
 @Test fun doubanCardsOnlyAcceptGenuineSubjectUrls(){val j=JSONObject("""{"cards":[{"type":"movie","url":"https://movie.douban.com/subject/36238849/","title":"玩具总动员5","year":"2026","card_subtitle":"8.0分 / 2026"},{"type":"movie","url":"https://untrusted.invalid/subject/123/","title":"wrong"},{"type":"book","url":"https://movie.douban.com/subject/3/","title":"wrong"}]}""");val rows=DoubanSearch055.cards(j);assertEquals(1,rows.size);assertEquals("8.0",rows.single().rating)}
 @Test fun ratingDoesNotConfuseSequelOrYearButAcceptsVerifiedAlias(){val w=Work("x","玩具总动员5","movie","2026");val names=MetadataQueries040.names(w);assertTrue(RatingMatch055.matches(w,Work("5","Toy Story 5","movie","2026",aliases=listOf("玩具总动员5")),names));assertFalse(RatingMatch055.matches(w,w.copy(id="4",title="玩具总动员4"),names));assertFalse(RatingMatch055.matches(w,w.copy(year="2019"),names));assertFalse(RatingMatch055.matches(w,w.copy(kind="tv"),names));assertFalse(RatingMatch055.matches(w.copy(title="玩具总动员第5部"),w.copy(title="玩具总动员第4部"),listOf("玩具总动员第5部")));assertFalse(RatingMatch055.matches(w.copy(title="剧集 第一季",kind="tv",season=1),w.copy(title="剧集 第二季",kind="tv",season=2),listOf("剧集 第一季")))}
 @Test fun outlineAndDiskRoundtripRetainPerEpisodeSynopsisAndIdentity(){val season=SeasonMeta(3,"第三季","2026",12);val outline=EpisodeRail055.outline("100","Show","Original",listOf(season),3);assertEquals((1..12).toList(),outline.episodes.map{it.number});assertTrue(outline.episodes.all{it.pending});val full=outline.copy(episodes=listOf(outline.episodes[2].copy(id="3003",overview="本集故事简介",votes=23,pending=false)));val result=EpisodeRail055.from(EpisodeRail055.json(full));assertEquals("本集故事简介",result.episodes.single().overview);assertEquals(3,result.episodes.single().number);assertEquals(23,result.episodes.single().votes);assertFalse(result.episodes.single().pending)}
 @Test fun keyboardPreservesUnicodeDeletionAndAllRequiredKeys(){assertEquals(42,SearchText055.keys.size);assertEquals(26,SearchText055.keys.count{it.matches(Regex("[A-Z]"))});assertEquals("片名",SearchText055.edit("片名😀","删除"));assertEquals("片名 ",SearchText055.edit("片名","空格"));assertEquals("",SearchText055.edit("","删除"))}
 @Test fun onlineHintsAreNamesNotTrustedMetadata(){val j=JSONObject("""{"data":[{"name":"玩具总动员5","year":2010,"aid":0},{"name":"玩具总动员5"},{"name":""},{"name":"玩具总动员4"}]}""");assertEquals(listOf("玩具总动员5","玩具总动员4"),SearchText055.suggestions(j));assertTrue(SearchText055.initialQuery("WJZDY"));assertFalse(SearchText055.initialQuery("Toy Story 5"))}
}
